css:
@import url("https://fonts.googleapis.com/css2?family=Bellefair&family=Commissioner:wght@300;400;600&display=swap");
:root{--tl:#1F3B3A;--tl2:#2C5250;--sg:#A8C3B8;--sgl:#DDE8E3;--sd:#EDE3D1;--sf:#D9A441;--gr:#51615F;--h:"Bellefair",Georgia,serif;--b:"Commissioner",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-weight:300;font-size:17px;line-height:1.7;color:var(--tl);background:var(--sgl)}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:400;margin:0;line-height:1.1}b,strong{font-weight:600}
.wrap{max-width:1160px;margin:0 auto;padding:0 24px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--sf);padding:8px;z-index:99}
:focus-visible{outline:2px solid var(--sf);outline-offset:3px}
.nav{display:flex;justify-content:space-between;align-items:center;height:86px;position:relative}.logo{font-family:var(--h);font-size:28px;text-decoration:none;display:flex;gap:10px;align-items:center}
.menu{display:flex;gap:30px;list-style:none;margin:0;padding:0;font-weight:400}.menu a{text-decoration:none}.menu a:hover{text-decoration:underline;text-underline-offset:5px}
.burger{display:none;background:none;border:1px solid var(--tl);color:var(--tl);width:44px;height:40px;border-radius:22px;font-size:18px;cursor:pointer}
.hero{padding:30px 0 90px}.hero .wrap{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}
.hero h1{font-size:clamp(46px,6vw,84px)}.hero p{font-size:19px;color:var(--gr);max-width:28em;margin:24px 0 32px}
.btn{display:inline-block;background:var(--tl);color:var(--sgl);text-decoration:none;font:400 16px var(--b);padding:15px 28px;border-radius:40px;border:0;cursor:pointer}.btn.l{background:transparent;color:var(--tl);box-shadow:inset 0 0 0 1px var(--tl)}
.row{display:flex;flex-wrap:wrap;gap:12px}
.breath{display:flex;flex-direction:column;align-items:center;text-align:center}
.ring{position:relative;width:min(420px,80vw);aspect-ratio:1;display:grid;place-items:center}
.ring svg{position:absolute;inset:0;width:100%;height:100%}
.orb{width:46%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 35% 35%,#F2DFB4,var(--sf) 55%,#B9832A);transform:scale(.6);transition:transform 4s ease-in-out;box-shadow:0 0 0 18px rgba(217,164,65,.15),0 0 0 40px rgba(217,164,65,.08)}
.orb.in{transform:scale(1.35)}.orb.hold{transform:scale(1.35)}
.cue{position:absolute;bottom:-54px;left:0;right:0;font-family:var(--h);font-size:30px}
.breath .ctl{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-top:76px}.breath small{display:block;color:var(--gr);margin-top:10px;font-size:15px}
.breath select{font:15px var(--b);padding:10px 14px;border-radius:30px;border:1px solid var(--tl);background:transparent;color:var(--tl)}
section{padding:90px 0}.sh{max-width:620px;margin-bottom:40px}.sh h2{font-size:clamp(38px,5vw,60px)}.sh p{color:var(--gr);margin:12px 0 0}
.sched{background:var(--tl);color:var(--sgl)}.sched .sh p{color:var(--sg)}
.lvl{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:30px}.lvl button{font:400 15px var(--b);background:transparent;color:var(--sgl);border:1px solid var(--tl2);border-radius:30px;padding:9px 18px;cursor:pointer}.lvl button[aria-pressed=true]{background:var(--sg);color:var(--tl);border-color:var(--sg)}
.wk{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10px}.wk>div{min-width:0}
.wk h3{font-size:22px;padding-bottom:10px;border-bottom:1px solid var(--tl2);margin-bottom:10px}.wk h3.td{color:var(--sf)}
.ci{background:var(--tl2);border-radius:12px;padding:12px;margin-bottom:10px;font-size:14px;line-height:1.4}.ci b{display:block;font-size:15px;font-weight:600}.ci span{color:var(--sg);display:block;margin-top:4px}
.ci.beg{box-shadow:inset 3px 0 0 var(--sf)}.empty{color:var(--sg);font-size:14px}
.path .wrap{display:grid;grid-template-columns:.9fr 1.1fr;gap:60px;align-items:center}
.path img{border-radius:220px 220px 16px 16px;width:100%;aspect-ratio:4/5;object-fit:cover}
.steps{list-style:none;padding:0;margin:0;counter-reset:s}.steps li{counter-increment:s;display:grid;grid-template-columns:56px 1fr;gap:18px;padding:18px 0;border-bottom:1px solid var(--sg)}
.steps li:before{content:counter(s);width:52px;height:52px;border-radius:50%;border:1px solid var(--tl);display:grid;place-items:center;font-family:var(--h);font-size:24px}
.steps h3{font-size:26px}.steps p{margin:4px 0 0;color:var(--gr)}
.pass{background:var(--sd)}.pp{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.ps{background:#fff;border-radius:18px;padding:28px 24px;display:flex;flex-direction:column}.ps.intro{background:var(--tl);color:var(--sgl)}
.ps h3{font-size:26px}.ps .pr{font-family:var(--h);font-size:56px;line-height:1;margin:14px 0 4px}.ps .per{font-size:14px;color:var(--gr);min-height:22px}.ps.intro .per{color:var(--sg)}
.ps p{flex:1;font-size:15px}.ps .btn{text-align:center;margin-top:10px}.ps.intro .btn{background:var(--sf);color:var(--tl)}
.visit .wrap{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}.visit img{border-radius:16px;width:100%;aspect-ratio:3/2;object-fit:cover}
footer{background:var(--tl);color:var(--sg);padding:34px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:1000px){.wk{grid-template-columns:repeat(4,minmax(0,1fr))}.pp{grid-template-columns:1fr 1fr}}
@media (max-width:820px){.hero .wrap,.path .wrap,.visit .wrap{grid-template-columns:1fr}.path img{max-width:380px}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:86px;left:0;right:0;background:var(--sgl);flex-direction:column;gap:14px;padding:18px 24px;z-index:30}.menu.open{display:flex}.wk{grid-template-columns:1fr 1fr}.pp{grid-template-columns:1fr}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.orb{transition:none;transform:scale(1)!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const D=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];const K={beg:"Beginner friendly",mix:"All levels",adv:"Experienced"};
const S=[[0,"07:00","Morning Flow","mix","Ana"],[0,"18:00","Gentle Basics","beg","Tom"],[1,"12:15","Lunch Stretch","beg","Ana"],[1,"19:00","Vinyasa","adv","Leah"],[2,"07:00","Morning Flow","mix","Leah"],[2,"18:00","Breath and Balance","beg","Tom"],[3,"18:30","Yin and Rest","mix","Ana"],[3,"19:45","Strong Flow","adv","Leah"],[4,"07:00","Slow Flow","beg","Tom"],[4,"17:30","Friday Unwind","mix","Ana"],[5,"09:00","Gentle Basics","beg","Tom"],[5,"10:30","Vinyasa","adv","Leah"],[6,"10:00","Slow Flow","beg","Ana"],[6,"17:00","Yin and Rest","mix","Tom"]];
let lv='all';const td=(new Date().getDay()+6)%7;
function draw(){$('wk').innerHTML=D.map((d,i)=>{const c=S.filter(s=>s[0]===i&&(lv==='all'||s[3]===lv));return`<div><h3 class="${i===td?'td':''}">${d}${i===td?' (today)':''}</h3>${c.length?c.map(s=>`<div class="ci ${s[3]}"><b>${s[1]} ${s[2]}</b><span>${K[s[3]]}, with ${s[4]}</span></div>`).join(''):'<p class="empty">No classes at this level</p>'}</div>`}).join('')}
$('lvl').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('lvl').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));lv=b.dataset.l;draw()};draw();
let timer=null,tick=null;const orb=$('orb'),cue=$('cue');
function stop(msg){clearTimeout(timer);clearInterval(tick);timer=null;orb.className='orb';$('go').textContent='Start 1 minute';$('go').setAttribute('aria-pressed','false');cue.textContent=msg||'Ready when you are';$('arc').style.strokeDashoffset=603;$('left').textContent='Follow the circle. Breathe in as it grows, out as it shrinks.'}
$('go').onclick=()=>{if(timer){stop();return}const p=$('pat').value.split(',').map(Number);const ph=[['Breathe in',p[0],'in'],['Hold',p[1],'hold'],['Breathe out',p[2],''],['Hold',p[3],'']].filter(x=>x[1]>0);
let end=Date.now()+60000,i=0;$('go').textContent='Stop';$('go').setAttribute('aria-pressed','true');
tick=setInterval(()=>{const r=Math.max(0,end-Date.now());$('arc').style.strokeDashoffset=603*r/60000;$('left').textContent=Math.ceil(r/1000)+' seconds left';if(!r)stop('Well done. How do you feel?')},250);
const step=()=>{if(Date.now()>=end)return;const x=ph[i%ph.length];orb.style.transitionDuration=x[1]+'s';orb.className='orb '+x[2];cue.textContent=x[0]+' ('+x[1]+')';i++;timer=setTimeout(step,x[1]*1000)};step()};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
